<?php $title='Admin dashboard';require '../includes/header.php';if(!is_admin())redirect('../auth/login.php');$count=$pdo->query('SELECT COUNT(*) c FROM products')->fetch()['c'];$orders=$pdo->query('SELECT COUNT(*) c FROM orders')->fetch()['c'];$users=$pdo->query('SELECT COUNT(*) c FROM users')->fetch()['c'];$revenue=$pdo->query("SELECT COALESCE(SUM(total),0) c FROM orders WHERE status!='Cancelled'")->fetch()['c'];$recent=$pdo->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 8')->fetchAll(); ?><section class="container section"><span class="eyebrow">CONTROL CENTER</span><h1>Admin dashboard</h1><div class="adminStats"><div><b><?=$count?></b><span>Products</span></div><div><b><?=$orders?></b><span>Orders</span></div><div><b><?=$users?></b><span>Customers</span></div><div><b>₹<?=number_format($revenue)?></b><span>Revenue</span></div></div><div class="sectionHead"><h2>Recent orders</h2><a class="btn dark" href="products.php">Manage products</a></div><div class="tableWrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($recent as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['name'])?></td><td>₹<?=number_format($r['total'])?></td><td><span class="status <?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td><td><?=date('d M Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></table></div></section><?php require '../includes/footer.php'; ?>